css:
.rocker {
  display: inline-block;
  position: relative;
  font-size: 14px;
  font-weight: bold;
  text-align: center;
  text-transform: uppercase;
  color: #888;
  width: 100px;
  height: 60px;
  overflow: hidden;
  border-bottom: 5px solid #1a1a1a;
}

.rocker input {
  opacity: 0;
  width: 0;
  height: 0;
}

.switch-left,
.switch-right {
  position: absolute;
  top: 5px;
  height: 100%;
  width: 100%;
  padding-top: 15px;
  transition: 0.2s;
}

.switch-left {
  left: -100%;
  background-color: #00e5ff;
  color: #000;
  transform: rotate(-15deg);
  transform-origin: 100% 0;
  box-shadow: 0 0 15px rgba(0, 229, 255, 0.6);
}

.switch-right {
  right: 0;
  background-color: #333;
  color: #fff;
  transform: rotate(0deg);
  transform-origin: 0 0;
}

.rocker input:checked + .switch-left {
  left: 0;
  transform: rotate(0deg);
}

.rocker input:checked + .switch-left + .switch-right {
  right: -100%;
  transform: rotate(15deg);
}
